using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;
public static class PolishHud06B{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var v=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>().Sandbox.RailwayHud.GetComponent<RailwayOverview>();var s=v.Services;s.ScrollHint=UnityEngine.Object.Instantiate(s.Feedback,s.Root);s.ScrollHint.name="ScrollHint";s.ScrollHint.text="휠로 아래 항목 보기";s.ScrollHint.alignment=TextAlignmentOptions.MidlineRight;s.ScrollHint.color=v.DetailText.color;s.CargoSummary.color=s.DefenseSummary.color=v.DetailText.color;foreach(var f in new[]{v.Railway.Resource,v.Railway.Load,v.Railway.Unload}){var im=f.GetComponent<UnityEngine.UI.Image>();if(im==null)im=f.gameObject.AddComponent<UnityEngine.UI.Image>();im.sprite=s.Return.GetComponent<UnityEngine.UI.Image>().sprite;im.type=UnityEngine.UI.Image.Type.Sliced;im.color=new Color(.7f,.8f,.8f,1);f.targetGraphic=im;}EditorUtility.SetDirty(s);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Saved scroll hint, neutral summaries and input boundaries";}}
